package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.*;import android.widget.*;import java.io.*;import java.util.*;
public final class StorageSettingsActivity extends LeoActivity {
    protected void onResume(){super.onResume();show();}
    private void show(){final LinkedHashMap<String,File> roots=LeoFileProvider.roots(this);final ArrayList<File> folders=new ArrayList<File>();final ArrayList<String> labels=new ArrayList<String>();folders.add(Environment.getDataDirectory());labels.add(L.t("Date interne · ")+capacity(Environment.getDataDirectory()));for(Map.Entry<String,File> root:roots.entrySet())if(!root.getKey().equals("leo")){folders.add(root.getValue());labels.add((root.getKey().equals("phone")?L.t("Fișiere telefon"):L.t("Card SD"))+" · "+capacity(root.getValue()));}final int locations=folders.size();labels.add(L.t("Salvare înregistrări · ")+RecordingLocations.label(this));labels.add(L.t("Descărcări · ")+(getSharedPreferences("downloads",0).getBoolean("wifi",true)?L.t("Numai Wi-Fi"):L.t("Wi-Fi și mobil")));labels.add(L.t("Fișiere Leo"));labels.add(L.t("Aplicații și spațiu APK"));labels.add(L.t("Analiză fișiere · categorii și fișiere mari"));labels.add(L.t("Salvare Leo · ")+(SaveLocations.key(this).equals("leo")?L.t("Telefon"):L.t("Card SD")));list(L.t("Stocare Leo"),labels,0,new Choice(){public void pick(int at){if(at<locations)details(folders.get(at));else if(at==locations)recordings();else if(at==locations+1)options(L.t("Rețeaua descărcărilor noi"),new String[]{L.t("Numai Wi-Fi"),L.t("Wi-Fi și date mobile")},new Choice(){public void pick(int n){getSharedPreferences("downloads",0).edit().putBoolean("wifi",n==0).apply();show();}});else if(at==locations+4)auditRoots();else if(at==locations+5)defaults();else startActivity(new Intent(StorageSettingsActivity.this,at==locations+2?FilesActivity.class:AppSettingsActivity.class));}},L.t("Actualiz."),new Runnable(){public void run(){show();}});}
    private int auditGeneration;
    private void auditRoots(){final LinkedHashMap<String,File> roots=LeoFileProvider.roots(this);final ArrayList<String> ids=new ArrayList<String>(roots.keySet()),names=new ArrayList<String>();for(String id:ids)names.add(id.equals("leo")?L.t("Documente Leo"):id.equals("phone")?L.t("Fișiere telefon"):L.t("Card SD"));list(L.t("Analizează locația"),names,0,new Choice(){public void pick(int i){audit(roots.get(ids.get(i)));}},"",null);back=new Runnable(){public void run(){show();}};}
    private void audit(final File folder){final int token=++auditGeneration;begin(L.t("Analizez fișierele"));root.addView(text(L.t("Citire în fundal…\nMaximum 12000 intrări / 10 secunde."),17));footer("","",L.t("Înapoi"));back=new Runnable(){public void run(){auditGeneration++;show();}};worker.execute(new Runnable(){public void run(){try{final StorageAudit.Result result=StorageAudit.scan(folder,12000,10000);ui(new Runnable(){public void run(){if(token!=auditGeneration)return;ArrayList<String> rows=new ArrayList<String>();for(int n=0;n<6;n++)rows.add(StorageAudit.CATEGORIES[n]+" · "+size(result.bytes[n]));rows.add(L.t("Fișiere mari · top ")+result.large.size());rows.add(result.files+L.t(" fișiere · ")+(result.partial?L.t("analiză parțială"):L.t("analiză încheiată"))+" · "+result.unreadable+L.t(" inaccesibile"));list(L.t("Categorii fișiere"),rows,0,new Choice(){public void pick(int n){if(n==6)large(folder,result);}},L.t("Actualiz."),new Runnable(){public void run(){audit(folder);}});back=new Runnable(){public void run(){auditRoots();}};}});}catch(Exception e){ui(new Runnable(){public void run(){if(token==auditGeneration){show();notice(L.t("Analiza nu este disponibilă"));}}});}}});}
    private String size(long n){return android.text.format.Formatter.formatFileSize(this,n);}
    private void large(final File folder,final StorageAudit.Result r){ArrayList<String> rows=new ArrayList<String>();for(File f:r.large)rows.add(f.getName()+"\n"+size(f.length()));list(L.t("Cele mai mari fișiere"),rows,0,new Choice(){public void pick(int n){final File f=r.large.get(n);options(f.getName(),new String[]{size(f.length()),f.getParent(),L.t("Deschide folderul în Fișiere")},new Choice(){public void pick(int k){if(k==2)startActivity(new Intent(StorageSettingsActivity.this,FilesActivity.class).putExtra("folder",f.getParent()));}});}},"",null);back=new Runnable(){public void run(){audit(folder);}};}
    private void defaults(){final LinkedHashMap<String,File> places=SaveLocations.folders(this);final ArrayList<String> keys=new ArrayList<String>(places.keySet()),names=new ArrayList<String>();for(String k:keys)names.add(k.equals("leo")?L.t("Telefon · Documente Leo"):L.t("Card SD · dosarele private Leo"));list(L.t("Exporturi și înregistrări noi"),names,Math.max(0,keys.indexOf(SaveLocations.key(this))),new Choice(){public void pick(final int n){if(RecordingService.instance!=null){notice(L.t("Oprește înregistrarea întâi"));return;}worker.execute(new Runnable(){public void run(){boolean good=false;File probe=null;try{File dir=places.get(keys.get(n));if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();probe=File.createTempFile(".leo-save-probe-",".tmp",dir);try(FileOutputStream stream=new FileOutputStream(probe)){stream.write(1);}good=probe.delete();}catch(IOException ignored){}finally{if(probe!=null&&probe.exists())probe.delete();}final boolean ok=good;ui(new Runnable(){public void run(){if(ok){getSharedPreferences("storage",0).edit().putString("exports",keys.get(n)).putString("recordings",keys.get(n)).apply();show();notice(L.t("Locație pentru fișiere noi salvată; descărcările păstrează Download"));}else notice(L.t("Locația nu permite scrierea"));}});}});}},"",null);back=new Runnable(){public void run(){show();}};}
    protected void onPause(){auditGeneration++;super.onPause();}
    static String capacity(File dir){try{StatFs stat=new StatFs(dir.getPath());return stat.getAvailableBytes()/1048576+L.t(" MiB liberi");}catch(RuntimeException e){return L.t("indisponibil");}}
    private void details(File dir){String value;try{StatFs stat=new StatFs(dir.getPath());long total=stat.getTotalBytes(),available=stat.getAvailableBytes();value="Total · "+total/1048576+L.t(" MiB\nLiber · ")+available/1048576+L.t(" MiB\nOcupat · ")+(total-available)/1048576+L.t(" MiB\nUtilizare · ")+(total>0?100-(int)(available*100/total):0)+L.t("%\n\nAceastă pagină nu execută formatare sau ștergere.");}catch(RuntimeException e){value=L.t("Stocare indisponibilă");}begin(L.t("Spațiu disponibil"));ScrollView scroll=new ScrollView(this);scroll.addView(text(value,18));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setFocusable(true);scroll.requestFocus();back=new Runnable(){public void run(){show();}};footer("",L.t("Derulează"),L.t("Înapoi"));}
    private void recordings(){final LinkedHashMap<String,File> places=RecordingLocations.folders(this);final ArrayList<String> keys=new ArrayList<String>(places.keySet()),labels=new ArrayList<String>();for(String key:keys)labels.add(key.equals("leo")?L.t("Telefon · Documente Leo"):L.t("Card SD · dosar privat Leo"));list(L.t("Salvare înregistrări"),labels,Math.max(0,keys.indexOf(RecordingLocations.key(this))),new Choice(){public void pick(final int at){if(RecordingService.instance!=null){notice(L.t("Oprește înregistrarea înainte de schimbarea locației"));return;}worker.execute(new Runnable(){public void run(){boolean writable=false;File probe=null;try{File dir=places.get(keys.get(at));if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();probe=File.createTempFile(".leo-storage-probe-",".tmp",dir);try(FileOutputStream out=new FileOutputStream(probe)){out.write(1);}writable=true;}catch(IOException e){}finally{if(probe!=null&&!probe.delete())writable=false;}final boolean ok=writable;ui(new Runnable(){public void run(){if(ok){getSharedPreferences("storage",0).edit().putString("recordings",keys.get(at)).apply();notice(L.t("Locație salvată; fișierele existente sunt păstrate"));show();}else notice(L.t("Locația nu permite scrierea"));}});}});}},"",null);back=new Runnable(){public void run(){show();}};}
}
